"use client";

/**
 * Eleeveon Schools: class-first batch ID browsing, preview and printing.
 * Entries come from the current Students/Teachers branch-scoped workspace.
 * No credential is generated by viewing or printing; issuance requires an
 * explicit user confirmation and a successful server response.
 */
import React, { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { db, type IdentityCredential } from "../../../lib/db/db";
import { identityApi, type IdentityCardResult, type IdentitySubject } from "./identityApi";
import IdentityCredentialCard, { type IdentityCredentialCardSubject } from "./IdentityCredentialCard";
import IdentityCredentialPrintSheet, { type PrintableCredential } from "./IdentityCredentialPrintSheet";
import { useIdentityCardPresentation } from "./identityCardPresentation";

const id = (value: unknown) => String(value ?? "").trim();
const isImage = (value: string) => /^(https?:\/\/|data:image\/|blob:|\/)/i.test(value);
const isSupabaseUrl = (value: string) => /supabase\.(co|in)\/storage\/v1\/object/i.test(value);
const millis = (value: unknown): number | undefined => {
  if (!value) return undefined;
  const time = new Date(value as string | number).getTime();
  return Number.isFinite(time) ? time : undefined;
};

export type BatchIdentityPerson = {
  id: string;
  name: string;
  classId?: string;
  className?: string;
  admissionNumber?: string;
  staffNumber?: string;
  organizationName?: string;
  gender?: string;
  dateOfBirth?: string;
  phone?: string;
  emergencyPhone?: string;
  photoUrl?: string;
  photoMediaId?: string;
};
export type BatchIdentityClass = { id: string; name: string };
type Lookup = { state: "ready" | "missing" | "inactive" | "unavailable"; card?: IdentityCardResult };

type Props = {
  open: boolean;
  onClose: () => void;
  subjectType: IdentitySubject;
  schoolId: string;
  branchId: string;
  accountId?: string | null;
  people: BatchIdentityPerson[];
  classes?: BatchIdentityClass[];
};

export default function IdentityCardBatch({
  open, onClose, subjectType, schoolId, branchId, accountId, people, classes = [],
}: Props) {
  const student = subjectType === "student";
  const { branding, academicYear, designFor, refresh } = useIdentityCardPresentation({
    accountId, schoolId, branchId,
  });
  const design = designFor(subjectType, "qr_code");
  const [scope, setScope] = useState<string | null>(null);
  const [step, setStep] = useState<"classes" | "people" | "preview">("classes");
  const [selected, setSelected] = useState<string[]>([]);
  const [lookups, setLookups] = useState<Record<string, Lookup>>({});
  const [images, setImages] = useState<Record<string, string[]>>({});
  const [search, setSearch] = useState("");
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState("");
  const [error, setError] = useState("");
  const [printOpen, setPrintOpen] = useState(false);
  const [previewPage, setPreviewPage] = useState(0);

  const groups = useMemo(() => {
    const result = classes.filter(c => id(c.id))
      .map(c => ({ ...c, count: people.filter(p => id(p.classId) === id(c.id)).length }));
    if (people.some(p => !id(p.classId) || !classes.some(c => id(c.id) === id(p.classId)))) {
      result.push({ id: "__unassigned__", name: "Unassigned", count: people.filter(p =>
        !id(p.classId) || !classes.some(c => id(c.id) === id(p.classId))).length });
    }
    return result.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
  }, [people, classes]);

  const scopePeople = useMemo(() => {
    if (!student || scope === "__all__") return people;
    if (scope === "__unassigned__") return people.filter(p =>
      !id(p.classId) || !classes.some(c => id(c.id) === id(p.classId)));
    return people.filter(p => id(p.classId) === scope);
  }, [student, scope, people, classes]);
  const visible = useMemo(() => scopePeople.filter(p =>
    !search.trim() || `${p.name} ${p.admissionNumber || ""} ${p.staffNumber || ""}`.toLowerCase()
      .includes(search.trim().toLowerCase())), [scopePeople, search]);
  const scopeName = !student ? "Teachers" : scope === "__all__" ? "All students" :
    scope === "__unassigned__" ? "Unassigned" : classes.find(c => id(c.id) === scope)?.name || "Class";
  const selectionSet = useMemo(() => new Set(selected), [selected]);
  const chosen = useMemo(() => scopePeople.filter(p => selectionSet.has(p.id)), [scopePeople, selectionSet]);
  const ready = useMemo(() => chosen.filter(p => lookups[p.id]?.state === "ready" &&
    Boolean(lookups[p.id]?.card?.verificationUrl)), [chosen, lookups]);
  const missing = chosen.filter(p => lookups[p.id]?.state === "missing").length;
  const unavailable = chosen.filter(p => lookups[p.id]?.state === "unavailable").length;
  const notReady = chosen.length - ready.length;

  useEffect(() => {
    if (open) {
      setScope(student ? null : "__all__");
      setStep(student ? "classes" : "people");
      setSelected([]); setLookups({}); setSearch("");
      setProgress(""); setError(""); setPreviewPage(0); setPrintOpen(false);
    }
  }, [open, student, schoolId, branchId]);

  useEffect(() => {
    if (!open || !schoolId || !branchId) return;
    let live = true;
    void db.mediaAssets.toArray().then(assets => {
      if (!live) return;
      const mapped: Record<string, string[]> = {};
      for (const person of people) {
        const matching = assets.filter(a => !a.isDeleted && a.active !== false &&
          (!accountId || !a.accountId || id(a.accountId) === id(accountId)) &&
          ((id(a.ownerTable) === (student ? "students" : "teachers") &&
            id(a.ownerId) === person.id && id(a.fieldKey) === "photo") ||
            (person.photoMediaId && id(a.id) === id(person.photoMediaId))));
        matching.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0));
        mapped[person.id] = Array.from(new Set([
          ...matching.flatMap(a => [a.publicUrl, a.remoteUrl, a.previewDataUrl, a.thumbnailDataUrl]),
          person.photoUrl,
        ].map(id).filter(isImage))).sort((a,b) => Number(isSupabaseUrl(b)) - Number(isSupabaseUrl(a)));
      }
      setImages(mapped);
    }).catch(e => console.warn("Could not load batch ID media", e));
    return () => { live = false; };
  }, [open, schoolId, branchId, accountId, student, people]);

  // A bounded worker pool protects the API when a whole class or branch is selected.
  const runPool = async (items: BatchIdentityPerson[], action: (person: BatchIdentityPerson) => Promise<void>, verb: string) => {
    let next = 0;
    let done = 0;
    setBusy(true); setError("");
    try {
      await Promise.all(Array.from({ length: Math.min(4, items.length) }, async () => {
        while (next < items.length) {
          const item = items[next++];
          try { await action(item); }
          catch (e) { console.warn(`Batch ID ${verb} failed`, item.id, e); }
          done++;
          setProgress(`${verb}: ${done} / ${items.length}`);
        }
      }));
    } finally { setBusy(false); }
  };

  const checkCards = async (items: BatchIdentityPerson[], enterPreview: boolean) => {
    if (!items.length) { setError("Select at least one person."); return; }
    const result: Record<string, Lookup> = {};
    await runPool(items, async p => {
      try {
        const card = await identityApi.get({ subjectType, subjectId: p.id, schoolId, branchId });
        result[p.id] = card.status === "active" && card.verificationUrl ? { state: "ready", card } :
          card.status === "not_issued" ? { state: "missing", card } : { state: "inactive", card };
      } catch { result[p.id] = { state: "unavailable" }; }
    }, "Checking IDs");
    setLookups(prev => ({...prev, ...result}));
    if (enterPreview) { setPreviewPage(0); setStep("preview"); refresh(); }
  };

  const issueMissing = async () => {
    const targets = chosen.filter(p => lookups[p.id]?.state === "missing");
    if (!targets.length) return;
    if (!window.confirm(`Issue ${targets.length} new ${student ? "student" : "teacher"} ID card(s)? Each will receive a public verification URL.`)) return;
    const result: Record<string, Lookup> = {};
    await runPool(targets, async p => {
      try {
        const card = await identityApi.issue({ subjectType, subjectId: p.id, schoolId, branchId });
        result[p.id] = card.status === "active" && card.verificationUrl ? {state:"ready",card} : {state:"inactive",card};
      } catch { result[p.id] = {state:"unavailable"}; }
    }, "Issuing IDs");
    setLookups(prev => ({...prev,...result}));
  };

  const printable = useMemo<PrintableCredential[]>(() => ready.map(p => {
    const card = lookups[p.id].card!;
    const subject: IdentityCredentialCardSubject = {
      fullName: p.name, admissionNumber: p.admissionNumber, staffNumber: p.staffNumber,
      className: p.className, organizationName: p.organizationName,
      academicYear, gender: p.gender, dateOfBirth: p.dateOfBirth,
      phone: p.phone, emergencyPhone: p.emergencyPhone,
      photoUrl: images[p.id]?.[0] || p.photoUrl || "",
      photoCandidates: images[p.id] || (p.photoUrl ? [p.photoUrl] : []),
    };
    const credential = {
      id: p.id, subjectId: p.id, subjectType, credentialType: "qr_code", status: "active",
      credentialReference: p.admissionNumber || p.staffNumber || "",
      generatedAt: millis(card.issuedAt), expiresAt: millis(card.expiresAt),
      metadata: { qrValue: card.verificationUrl! },
    } as Partial<IdentityCredential>;
    return { credential, subject };
  }), [ready, lookups, subjectType, academicYear, images]);

  if (!open || typeof document === "undefined") return null;
  const previewSize = 20;
  const previewCount = Math.max(1, Math.ceil(printable.length / previewSize));
  const page = Math.min(previewPage, previewCount - 1);
  const currentPreview = printable.slice(page * previewSize, (page + 1) * previewSize);
  const buttonStyle: React.CSSProperties = { cursor: "pointer", padding: "9px 13px", border: "1px solid var(--border,#cbd5e1)",
    background: "var(--surface,#fff)", color: "var(--text,#111827)", borderRadius: 10, fontSize: 12 };
  const primaryStyle: React.CSSProperties = {...buttonStyle, background: "var(--primary-color,#2563eb)",
    borderColor: "var(--primary-color,#2563eb)", color: "white", fontWeight: 700};
  const cardBox: React.CSSProperties = { display: "flex", alignItems: "center", gap: 12, padding: 13,
    border: "1px solid var(--border,#dbe2eb)", borderRadius: 12, background: "var(--surface,#fff)",
    color: "var(--text,#111827)", width: "100%", textAlign: "left", minHeight: 65 };

  return <>{createPortal(<div className="el-batch-backdrop" role="dialog" aria-modal="true" aria-label="Batch ID cards">
    <style>{`
      .el-batch-backdrop{position:fixed;inset:0;z-index:2147482500;background:#020617bd;display:flex;justify-content:center;align-items:center;padding:12px}
      .el-batch-panel{background:var(--card-bg,var(--surface,#fff));color:var(--text,#111827);border-radius:16px;width:min(100%,1000px);max-height:95dvh;display:flex;flex-direction:column;overflow:hidden}
      .el-batch-head{padding:14px 16px;border-bottom:1px solid var(--border,#cbd5e144);display:flex;align-items:center;justify-content:space-between;gap:8px}
      .el-batch-content{padding:14px 16px;overflow:auto;min-height:0;flex:1}
      .el-batch-list{display:grid;grid-template-columns:1fr;gap:9px}
      .el-batch-footer{border-top:1px solid var(--border,#cbd5e144);padding:12px 16px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:flex-end}
      .el-batch-preview-card{display:flex;flex-wrap:wrap;justify-content:center;gap:15px;align-items:flex-start;padding:15px;break-inside:avoid}
      .el-batch-check{accent-color:var(--primary-color,#2563eb);width:17px;height:17px;flex-shrink:0}
      .el-batch-backdrop button:disabled{opacity:.45;cursor:not-allowed!important}
      .el-batch-class-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:9px}
      @media(max-width:550px){.el-batch-panel{max-height:100dvh;height:100dvh;border-radius:0}.el-batch-backdrop{padding:0}.el-batch-preview-card{padding:8px;overflow-x:auto}}
      @media print{.el-batch-backdrop{display:none!important}}
    `}</style>
    <section className="el-batch-panel">
      <div className="el-batch-head"><div style={{display:"flex",alignItems:"center",gap:9,minWidth:0,flexWrap:"wrap"}}>
        {step !== "classes" && student && <button type="button" style={buttonStyle} onClick={() => {
          if (step === "preview") { setStep("people"); } else { setStep("classes"); setScope(null); setSelected([]); setSearch(""); }
        }}>{step === "people" ? "← Classes" : "← Students"}</button>}
        {step === "preview" && !student && <button type="button" style={buttonStyle} onClick={() => setStep("people")}>← Teachers</button>}
        <strong style={{fontSize:14}}>{step === "classes" ? "Batch Student ID Cards" : scopeName}</strong>
      </div><button type="button" style={buttonStyle} onClick={onClose}>✕ Close</button></div>
      <div className="el-batch-content">
        {step === "classes" && <><p style={{fontSize:12,opacity:.75,marginTop:0}}>Choose a class to preview and print its ID cards.</p>
          <div className="el-batch-class-grid"><button type="button" style={{...cardBox,cursor:"pointer"}} onClick={() => {setScope("__all__");setSelected([]);setStep("people");}}>
            <strong style={{flex:1}}>All students</strong><small>{people.length}</small> <span>›</span>
          </button>{groups.map(group => <button type="button" key={group.id} style={{...cardBox,cursor:"pointer"}} onClick={() => {setScope(group.id);setSelected([]);setStep("people");}}>
            <strong style={{flex:1}}>{group.name}</strong><small>{group.count}</small> <span>›</span>
          </button>)}</div></>}
        {step === "people" && <>
          <p style={{fontSize:12,opacity:.75,marginTop:0}}>Select the people to preview or print. Only IDs with an active verification link can be printed.</p>
          <div style={{display:"flex",gap:9,flexWrap:"wrap",alignItems:"center",marginBottom:12}}>
            <input aria-label="Find a person" value={search} onChange={e => setSearch(e.target.value)} placeholder={`Search ${student ? "students" : "teachers"}`}
              style={{flex:"1 1 180px",padding:10,border:"1px solid var(--border,#cbd5e1)",borderRadius:10,background:"var(--surface,#fff)",color:"inherit"}}/>
            <button type="button" style={buttonStyle} onClick={() => setSelected(prev => Array.from(new Set([...prev,...visible.map(p => p.id)])))}>Select visible</button>
            <button type="button" style={buttonStyle} onClick={() => setSelected([])}>Clear</button>
          </div>
          <div className="el-batch-list">{visible.map(p => <label key={p.id} style={{...cardBox,cursor:"pointer"}}>
            <input className="el-batch-check" type="checkbox" checked={selectionSet.has(p.id)} onChange={e => setSelected(prev => e.target.checked ? [...prev,p.id] : prev.filter(v => v !== p.id))}/>
            <span style={{flex:1,minWidth:0}}><strong style={{display:"block",fontSize:13}}>{p.name}</strong>
              <small style={{fontSize:11,opacity:.7}}>{p.admissionNumber || p.staffNumber || "No ID number"}{student && p.className ? ` · ${p.className}` : ""}</small></span>
            {lookups[p.id]?.state === "ready" ? <small style={{color:"#15803d"}}>Ready</small> :
              lookups[p.id]?.state === "missing" ? <small>Not issued</small> :
              lookups[p.id]?.state === "unavailable" ? <small>Not checked</small> : null}
          </label>)}{!visible.length && <p style={{opacity:.65,fontSize:12}}>No people found in this selection.</p>}</div>
        </>}
        {step === "preview" && <>
          <p style={{fontSize:12,opacity:.8,marginTop:0}}>{ready.length} ready for preview and printing · {notReady} without an active ID
            {missing > 0 ? ` · ${missing} not issued` : ""}{unavailable > 0 ? ` · ${unavailable} unavailable` : ""}</p>
          {missing > 0 && <button disabled={busy} type="button" style={buttonStyle} onClick={() => void issueMissing()}>Issue {missing} missing ID{missing === 1 ? "" : "s"}</button>}
          {!ready.length && <p style={{padding:16,fontSize:13,opacity:.75}}>There are no active IDs to preview. Check connectivity or issue missing IDs explicitly.</p>}
          <div style={{display:"grid",gap:12,marginTop:14}}>{currentPreview.map((item, index) => <article key={item.credential.subjectId || index}
            style={{border:"1px solid var(--border,#cbd5e1)",borderRadius:12,overflow:"hidden"}}>
            <div style={{padding:"8px 12px",background:"var(--surface-muted,#f1f5f9)",color:"var(--text,#111827)",fontSize:12,fontWeight:600}}>{page * previewSize + index + 1}. {item.subject.fullName}</div>
            <div className="el-batch-preview-card"><IdentityCredentialCard design={design} credential={item.credential} subject={item.subject} branding={branding}/>
              {design.sides === "front_and_back" && <IdentityCredentialCard side="back" design={design} credential={item.credential} subject={item.subject} branding={branding}/>}</div>
          </article>)}</div>
          {previewCount > 1 && <div style={{display:"flex",gap:8,justifyContent:"center",marginTop:14,alignItems:"center"}}>
            <button type="button" style={buttonStyle} disabled={page===0} onClick={() => setPreviewPage(p => Math.max(0,p-1))}>Previous</button>
            <small>Page {page+1} of {previewCount}</small>
            <button type="button" style={buttonStyle} disabled={page>=previewCount-1} onClick={() => setPreviewPage(p => p+1)}>Next</button>
          </div>}
        </>}
        {(progress || error) && <p role="status" style={{fontSize:12,color:error?"#b91c1c":"inherit"}}>{error || progress}</p>}
      </div>
      <footer className="el-batch-footer">
        <small style={{marginRight:"auto",fontSize:11,opacity:.75}}>{step === "people" ? `${selected.length} selected` : step === "preview" ? `${ready.length} printable` : `${people.length} records`}</small>
        {step === "people" && <button type="button" disabled={busy || !selected.length} style={primaryStyle} onClick={() => void checkCards(chosen,true)}>{busy ? progress || "Checking..." : `Preview IDs (${selected.length})`}</button>}
        {step === "preview" && <>
          <button type="button" style={buttonStyle} disabled={busy} onClick={() => {setStep("people");}}>Change selection</button>
          <button type="button" style={buttonStyle} disabled={busy} onClick={() => void checkCards(chosen,true)}>Refresh IDs</button>
          <button type="button" style={primaryStyle} disabled={busy || !ready.length} onClick={() => setPrintOpen(true)}>Print {ready.length} IDs</button>
        </>}
      </footer>
    </section>
  </div>, document.body)}
  {printOpen && createPortal(<IdentityCredentialPrintSheet open={printOpen}
    onClose={() => setPrintOpen(false)} design={design} branding={branding}
    credentials={printable} title={`${scopeName} · ID Cards`}/>, document.body)}
  </>;
}
